INSERT OR IGNORE INTO 'task_record'('id', 'task_id', 'filename', 'file_size', 'status', 'user_id', 'remaining_bonus', 'record_id', 'progress', 'result', 'error', 'metadata_json', 'validation_json', 'summary_json', 'trace_id', 'created_at', 'updated_at') VALUES (26, 'cbe57f96-7856-448d-b494-dff19c6ad1a2', '同一房屋买卖合同签订三份“阴阳合同”，法院如何认定效力？.txt', 3950, 'completed', 1, 4, 1, 100, replace('# 合同审查报告\n\n---\n\n1. 审查前提\n本案合同属于房屋买卖合同，【法律关系性质】: 买卖关系，关键审查前提是：1. 合同双方的真实意思表示；2. 合同内容是否违反法律法规的强制性规定或公序良俗。\n\n3. 结论与行动建议\n**应该怎么做**：英子应当按照2021年11月18日签订的《房地产转让协议书》支付剩余购房款42万元。\n**为什么**：依据意思自治原则、诚实信用原则和公平原则，2021年11月18日签订的《房地产转让协议书》反映了双方的真实意思表示，且内容详尽，应当维持其效力。此外，2021年11月19日签订的《房地产转让协议书》因存在规避税费的目的而无效。\n\n---\n*本报告由AI生成，仅供参考，如有疑问请联系专业人士。*\n\n---\n\n*报告生成时间：2026-06-13 10:31:20*\n*模型版本：qwen-plus*\n','\n', char(10)), NULL, '{"timestamp": "2026-06-13 10:31:20", "model_version": "qwen-plus", "confidence_score": null, "validation_status": "warning", "has_warnings": true, "warnings": ["格式检查: 缺少章节 - 风险评估", "置信度检查: 未找到置信度数值", "来源检查: 缺失标记 - 【判决原文】", "一致性检查: 报告中未提取到核心结论"], "format_check_status": "warning", "confidence_check_status": "warning", "source_check_status": "warning", "contract_text": "近日，广西壮族自治区南丹县人民法院审理了一起关于“阴阳合同”的房屋买卖合同纠纷案件。买卖双方在对同一套房屋进行交易时，先后签订了三份《房地产转让协议书》及一份补充协议，法院如何认定哪一份协议有效呢？\r\n\r\n　　2021年11月18日，萧晓、英子签订《房地产转让协议书》，双方约定：萧晓将坐落于南丹县城关镇某地的房地产转让给英子，总金额为人民币82万元，分两次付款，英子在协议生效即日将该房地产转让定金人民币40万元付给萧晓，萧晓收到英子第一次付款后，四个月内帮英子办理过户手续过户到其名下，过户所产生的所有费用由萧晓负责。不动产权证办理好后，英子交清余款，萧晓交付房屋，并约定了双方违约时各自所应承担的责任条款。\r\n\r\n　　2021年11月19日，萧晓、英子又协商签订一份新的《房地产转让协议书》，约定上述萧晓的房地产售价总额为人民币50万元，调整过户费用由英子承担，其余约定事项与11月18日签订的协议不变。\r\n\r\n　　2021年11月19日，双方约定：经双方再次协商，办理房地产转让手续所需税费，由双方各自承担各自所应支付的部分，除此之外，所有一切均按原协议执行。\r\n\r\n　　萧晓担心之后双方就交易价格发生争议，遂与英子协商后，由案外人福宝在18日所签订的《房地产转让协议书》的第二页尾部备注：“所有交付款项均以收据为凭，甲乙双方交易金额以此份协议为准”。\r\n\r\n　　以上协议签订后，萧晓向按程序向南丹县自然资源局补交土地出让金后将办理房地产转让相关手续……\r\n\r\n　　2022年7月8日，萧晓缴纳土地出让金27.9万余元及相应税费，由于原来提交的协议书已经过期，双方当日又重新签订了一份《房地产转让协议书》（与2021年11月19日签订的协议内容相同），并交至税务部门及不动产中心，双方于2022年7月11日完成办理房地产变更登记全部手续。\r\n\r\n　　萧晓依约将转让的房地产登记至英子名下后，萧晓以英子未按合同约定支付购房尾款420000元构成违约为由，向南丹法院提起诉讼，英子在诉讼过程中提起反诉。\r\n\r\n　　萧晓认为，我们在2021年11月18日签订的那份《房地产转让协议书》，是合法有效的，19日签订的那份是英子为了降低缴纳税费才签订的，而且我们都在18日签订的协议书上注明双方交易金额是以此份协议为准。英子应交清余款42万元给我。\r\n\r\n　　英子认为，我们2021年11月19日的《房地产转让协议书》，是在双方协商一致的基础上签订的，该协议已经替代了18日签的那份协议，并且在过户期间经税收部门房产价值评估，该房产价值为50万元，与19日协议约定的房屋售价总额50万元一致，我不是为了避税，我要求法院确认2021年11月19日及2022年7月8日签订的《房地产转让协议书》合法有效。\r\n\r\n　　法院组织双方当事人进行了质证，根据合同签订过程、日常情理以及双方签订协议时其他在场人的陈述等情况，综合认定如下：\r\n\r\n　　认定2021年11月18日签订《房地产转让协议书》以及2021年11月19日签订的《房地产转让补充协议书》，系双方真实意思表示并实际履行的合同。\r\n\r\n　　从两份交易金额不同的合同所约定内容审查，18日签订的合同对各相关事项均作出了详细约定，更能体现其真实性，法院予以支持。而第二、三份签订的合同（内容一致）内容较为简单，对部分事项均无明确约定，从日常情理分析其目的是减少税费，更具有合理性和可能性，是虚假通谋的意思表示，属于无效合同。\r\n", "file_hash": "4fb092d842e7d738f54ec981677a9a24"}', '{"has_warnings": true, "warnings": ["格式检查: 缺少章节 - 风险评估", "置信度检查: 未找到置信度数值", "来源检查: 缺失标记 - 【判决原文】", "一致性检查: 报告中未提取到核心结论"], "confidence_score": null}', '{"risk_level": "未知", "risk_count": 0, "suggestion_count": 1, "confidence": null}', 'trace_mqbqlx4i_4s19ev57s', '2026-06-13 02:29:35', '2026-06-13 02:31:20');
